let mapView={x:0,y:0,zoom:1},stopMapView=()=>{};
function mapHtml(max){return `<section class="ud-map" aria-label="日本のうにメン分布"><div class="ud-map-head"><strong>全国の分布</strong><div class="ud-map-tools"><button type="button" data-ud-zoom="out" aria-label="地図を縮小">−</button><output class="ud-map-scale">${Math.round(mapView.zoom*100)}%</output><button type="button" data-ud-zoom="in" aria-label="地図を拡大">＋</button><button type="button" data-ud-zoom="fit">全体</button></div></div><div class="ud-map-viewport"><svg class="ud-japan-map" viewBox="0 0 800 680" role="group" aria-label="都道府県を選択"><g class="ud-okinawa-inset"><rect x="15" y="530" width="165" height="127" rx="10"/><text x="34" y="549" class="ud-inset-label">沖縄</text></g>${MAP_GEO.map(g=>`<g role="button" tabindex="0" data-ud-pref="${g.name}" aria-label="${g.name} ${count(g.name)}人" aria-pressed="${pref===g.name}" style="--intensity:${count(g.name)?(.25+.65*count(g.name)/max):0}"><title>${g.name} ${count(g.name)}人</title><path class="ud-pref-shape" d="${g.path}"/></g>`).join('')}<g class="ud-map-labels" aria-hidden="true">${MAP_GEO.map(g=>`<text class="ud-pref-label" data-map-label="${g.name}" x="${g.label[0]}" y="${g.label[1]}" style="display:none"><tspan x="${g.label[0]}" dy="-.2em">${g.name}</tspan><tspan x="${g.label[0]}" dy="1.2em">${count(g.name)}人</tspan></text>`).join('')}</g></svg></div><div class="ud-map-legend"><span>少ない</span><i aria-hidden="true"></i><span>多い</span></div><small>拡大すると県名・人数を表示／ピンチ・ドラッグ対応</small><span class="ud-map-credit">出典：国土数値情報（加工）</span></section>`;}
function bindMap(){
 const viewport=$('.ud-map-viewport',modal),svg=$('.ud-japan-map',modal);if(!svg)return;
 const apply=()=>{
  svg.setAttribute('viewBox',`${mapView.x} ${mapView.y} ${800/mapView.zoom} ${680/mapView.zoom}`);$('.ud-map-scale',modal).textContent=Math.round(mapView.zoom*100)+'%';
  const scale=Math.max(.01,svg.clientWidth/800*mapView.zoom),font=11/scale,boxes=[];
  for(const g of MAP_GEO){const label=svg.querySelector(`[data-map-label="${g.name}"]`),width=g.name.length*font,height=2.4*font;
   const box={x:g.label[0]-width/2,y:g.label[1]-font,w:width,h:height};
   const fits=g.name==='沖縄県'||g.radius*scale>=Math.max(9,g.name.length*2.4),collides=boxes.some(b=>box.x<b.x+b.w&&box.x+box.w>b.x&&box.y<b.y+b.h&&box.y+box.h>b.y);
   const visible=mapView.zoom>=1.7&&fits&&!collides;label.style.display=visible?'':'none';label.style.fontSize=font+'px';if(visible)boxes.push(box);
  }
 };

 const point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());};
 const zoom=(factor,anchor)=>{const old=mapView.zoom,next=Math.min(12,Math.max(.75,old*factor));const c=anchor||{x:mapView.x+400/old,y:mapView.y+340/old};mapView.x=c.x-(c.x-mapView.x)*old/next;mapView.y=c.y-(c.y-mapView.y)*old/next;mapView.zoom=next;apply();};
 $('.ud-map-tools',modal).onclick=e=>{const b=e.target.closest('[data-ud-zoom]');if(!b)return;if(b.dataset.udZoom==='fit'){mapView={x:0,y:0,zoom:1};apply();}else zoom(b.dataset.udZoom==='in'?1.25:.8);};
 const pointers=new Map();let moved=false,lastDistance=0;
 viewport.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return; if(!pointers.size)moved=false;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});e.target.setPointerCapture(e.pointerId);lastDistance=0;});
 viewport.addEventListener('pointermove',e=>{const old=pointers.get(e.pointerId);if(!old)return;const dx=e.clientX-old.x,dy=e.clientY-old.y;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(Math.abs(dx)+Math.abs(dy)>2)moved=true;
  if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(lastDistance>0)zoom(distance/lastDistance,point({clientX:(a.x+b.x)/2,clientY:(a.y+b.y)/2}));lastDistance=distance;}else{const now=point(e),before=point({clientX:old.x,clientY:old.y});mapView.x-=now.x-before.x;mapView.y-=now.y-before.y;apply();}
 });
 const end=e=>{pointers.delete(e.pointerId);lastDistance=0;};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);
 viewport.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);
 viewport.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.002),point(e));},{passive:false});
 svg.addEventListener('keydown',e=>{const target=e.target.closest('[data-ud-pref]');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});const observer=new ResizeObserver(apply);observer.observe(viewport);stopMapView=()=>observer.disconnect();apply();
}
let rows=[],tab='list',region='',pref='',query='',month=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Tokyo',month:'numeric'}).format(new Date())),ready=false,failed=false,unsubscribe=null,focusReturn=null;
const positions={};const modal=$('#prefectureDirectoryModal'),panel=$('.prefecture-directory-panel',modal);
function count(p){return rows.filter(x=>x.prefecture===p).length;}
function isMember(){try{return !!JSON.parse(localStorage.getItem('unicaWorldMemberV4')||localStorage.getItem('unicaWorldMemberV3')||'null')}catch{return false;}}
function jst(){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Tokyo',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date());return Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));}
function validBirthday(u){const m=Number(u.birthMonth),d=Number(u.birthDay);return u.birthdayPublic!==false&&Number.isInteger(m)&&m>=1&&m<=12&&Number.isInteger(d)&&d>=1&&d<=new Date(Date.UTC(2000,m,0)).getUTCDate();}
function nextBirthday(u){const t=jst(),now=Date.UTC(t.year,t.month-1,t.day);let year=t.year;let date=Date.UTC(year,Number(u.birthMonth)-1,Number(u.birthDay));if(date<now)date=Date.UTC(++year,Number(u.birthMonth)-1,Number(u.birthDay));return Math.round((date-now)/86400000);}
function memberRow(u,birth=false){return `<button class="ud-person" type="button" data-ud-person="${esc(u.uid)}"><span class="ud-avatar">${window.UNICA_BLOOM_BADGE?.html?.(u,'normal')||'<span aria-hidden="true">◆</span>'}</span><span class="ud-person-copy"><strong>${esc(u.name||'うにメン')}</strong><small>No.${esc(u.number||'—')}${u.prefecturePublic!==false&&u.prefecture?' · '+esc(u.prefecture):''}</small></span>${birth?`<time>${Number(u.birthMonth)}/${Number(u.birthDay)}</time>`:'<span aria-hidden="true">›</span>'}</button>`;}
function listHtml(data,birth=false){return data.length?data.map(u=>memberRow(u,birth)).join(''):'<p class="ud-empty">該当するうにメンはいません。</p>';}
function regionHtml(){const max=Math.max(1,...PREFS.map(count));return `${mapHtml(max)}<div class="ud-region-grid">${REGIONS.map(([name,ps])=>`<button type="button" data-ud-region="${name}" aria-pressed="${region===name}"><strong>${name}</strong><span>${ps.reduce((a,p)=>a+count(p),0)}人</span></button>`).join('')}</div>${region?`<h3>${region}</h3><div class="ud-pref-grid">${REGIONS.find(x=>x[0]===region)[1].map(p=>`<button type="button" data-ud-pref="${p}" aria-pressed="${pref===p}">${p}<b>${count(p)}人</b></button>`).join('')}</div>`:''}${pref?`<section id="udSelected"><h3>${pref} <small>${count(pref)}人</small></h3>${listHtml(rows.filter(u=>u.prefecture===pref&&u.prefecturePublic!==false))}${rows.some(u=>u.prefecture===pref&&u.prefecturePublic===false)?'<p class="ud-note">人数には地域を非公開にしているメンバーも含まれます。</p>':''}</section>`:''}${rows.some(u=>!PREFS.includes(u.prefecture))?`<p class="ud-note">地域未登録・その他：${rows.filter(u=>!PREFS.includes(u.prefecture)).length}人</p>`:''}`;}
function birthdayHtml(){const all=rows.filter(validBirthday),t=jst(),today=all.filter(u=>Number(u.birthMonth)===t.month&&Number(u.birthDay)===t.day),soon=all.filter(u=>nextBirthday(u)>0).sort((a,b)=>nextBirthday(a)-nextBirthday(b)).slice(0,5),monthly=all.filter(u=>Number(u.birthMonth)===month).sort((a,b)=>a.birthDay-b.birthDay||Number(a.number)-Number(b.number));return `<section class="ud-today"><h3>今日のお誕生日</h3>${today.length?listHtml(today,true):'<p>今日はお誕生日のうにメンはいません。</p>'}</section><h3>もうすぐお誕生日</h3>${soon.length?soon.map(u=>`<div class="ud-soon"><small>あと${nextBirthday(u)}日</small>${memberRow(u,true)}</div>`).join(''):'<p class="ud-empty">公開中の誕生日がありません。</p>'}<label class="ud-month">月別に見る <select id="udMonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${i+1}月</option>`).join('')}</select></label><h3>${month}月 <small>${monthly.length}人</small></h3>${listHtml(monthly,true)}`;}
function render(){const box=$('#prefectureDirectoryList');if(!box)return;stopMapView();$('#prefectureDirectoryTotal').textContent=ready?rows.length:'—';box.className='ud-content';box.innerHTML=`<nav class="ud-tabs" role="tablist" aria-label="うにメンの表示">${[['list','一覧'],['region','地域'],['birthday','誕生日']].map(([key,name])=>`<button type="button" role="tab" id="udTab-${key}" aria-controls="udView" aria-selected="${tab===key}" data-ud-tab="${key}">${name}</button>`).join('')}</nav><div id="udView" role="tabpanel" aria-labelledby="udTab-${tab}">${!ready?`<p class="ud-empty">${failed?'読み込めませんでした。通信を確認して再度開いてください。':'読み込み中…'}</p>`:tab==='list'?`<label class="ud-search">名前・会員番号で検索<input type="search" id="udSearch" value="${esc(query)}" placeholder="名前・会員番号"></label><div id="udPeople">${listHtml(rows.filter(u=>`${u.name||''} ${u.number||''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(a.number||1e9)-Number(b.number||1e9)))}</div>`:tab==='region'?regionHtml():birthdayHtml()}</div>`;bindMap();}
function setOpen(open){if(!open)positions[tab]=panel.scrollTop;if(!open)stopMapView();modal.classList.toggle('is-open',open);modal.setAttribute('aria-hidden',!open);document.body.classList.toggle('modal-open',!!$('.world-modal.is-open'));if(open){focusReturn=document.activeElement;render();panel.scrollTop=positions[tab]||0;$('.ud-tabs button[aria-selected="true"]')?.focus({preventScroll:true});}else focusReturn?.focus?.({preventScroll:true});}
function home(){const top=REGIONS.map(([name,ps])=>({name,count:ps.reduce((a,p)=>a+count(p),0)})).filter(x=>x.count).sort((a,b)=>b.count-a.count).slice(0,3);$('#prefectureTotalMembers')&&($('#prefectureTotalMembers').textContent=rows.length+'人');$('#prefectureHomeRanking')&&($('#prefectureHomeRanking').innerHTML='<p class="ud-note">一覧・地域・誕生日から仲間を探せます。</p>');window.dispatchEvent(new CustomEvent('unica:prefecture-summary',{detail:{total:rows.length,top}}));}
function open(){if(!isMember()){document.getElementById('openMemberGate')?.click();return;}setOpen(true);}
// Keep the public entry used by the existing home buttons.
window.UNICA_PREFECTURE_DIRECTORY={
 open,
 openMembers(prefecture){
  if(!PREFS.includes(prefecture))return;
  tab='region';pref=prefecture;region=REGIONS.find(x=>x[1].includes(pref))[0];open();
 }
};
$('#prefectureDirectoryTitle').textContent='うにメン';$('.prefecture-directory-intro').textContent='仲間を探したり、地域や誕生日を見られます。';$('#openPrefectureDirectory').innerHTML='うにメンを見る <span>›</span>';
$('#openPrefectureDirectory').addEventListener('click',open);document.querySelectorAll('[data-close-prefecture-directory]').forEach(el=>el.addEventListener('click',()=>setOpen(false)));
modal.addEventListener('click',e=>{const b=e.target.closest('button,[data-ud-pref]');if(!b)return;if(b.dataset.udTab){positions[tab]=panel.scrollTop;tab=b.dataset.udTab;render();panel.scrollTop=positions[tab]||0;$('#udTab-'+tab)?.focus({preventScroll:true});}else if(b.dataset.udRegion){region=b.dataset.udRegion;pref='';render();}else if(b.dataset.udPref){pref=b.dataset.udPref;region=REGIONS.find(x=>x[1].includes(pref))[0];render();$('#udSelected')?.scrollIntoView({block:'nearest'});}else if(b.dataset.udPerson){positions[tab]=panel.scrollTop;setOpen(false);window.dispatchEvent(new CustomEvent('unica:open-member-pass',{detail:{uid:b.dataset.udPerson}}));}});
modal.addEventListener('input',e=>{if(e.target.id==='udSearch'){query=e.target.value;$('#udPeople').innerHTML=listHtml(rows.filter(u=>`${u.name||''} ${u.number||''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(a.number||1e9)-Number(b.number||1e9)));}});
modal.addEventListener('change',e=>{if(e.target.id==='udMonth'){month=Number(e.target.value);const offset=panel.scrollTop;render();panel.scrollTop=offset;$('#udMonth')?.focus({preventScroll:true});}});
modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();setOpen(false);}if(e.key==='Tab'){const focusable=[...panel.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function start(){const api=window.UNICA_FIREBASE;if(!api?.db||unsubscribe)return false;unsubscribe=onSnapshot(collection(api.db,'users'),snap=>{rows=snap.docs.map(d=>({...d.data(),uid:d.id}));ready=true;failed=false;home();if(modal.classList.contains('is-open')){const offset=panel.scrollTop;render();panel.scrollTop=offset;}},()=>{failed=true;ready=false;if(modal.classList.contains('is-open'))render();});return true;}start();window.addEventListener('unica:firebase-ready',start);let retries=0;const timer=setInterval(()=>{if(start()||unsubscribe||++retries>=40)clearInterval(timer)},250);
function renameEntry(){const b=document.querySelector('[data-feature-key="prefecture"]');if(!b)return false;const title=b.querySelector('strong,b');if(title)title.textContent='うにメン';else if(b.textContent.includes('全国のうにメン'))b.textContent='うにメン';b.setAttribute('aria-label','うにメン一覧を開く');return true;}
if(!renameEntry()){const observer=new MutationObserver(()=>{if(renameEntry())observer.disconnect()});observer.observe(document.body,{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),10000);}
